<script setup lang="ts">
import { MapPin, Clock3, Leaf, Navigation, BookOpen } from '@lucide/vue'
import { places, mapsUrl, placeImageAlt, placeImageAttribution } from '~/data/places'
const route = useRoute()
const { asset, absoluteAsset } = useSiteUrls()
const place = places.find(item => item.slug === route.params.slug)
if (!place) throw createError({ statusCode: 404, statusMessage: 'ไม่พบจุดแวะนี้' })
const imageAttribution = placeImageAttribution(place)
useSeoMeta({ title: `${place.title} | บางหลวง วันว่าง`, description: place.description, ogTitle: `${place.title} | บางหลวง วันว่าง`, ogDescription: place.description, ogImage: absoluteAsset(place.image) })
</script>

<template><div v-if="place"><SiteHeader /><main class="shell detail-page"><nav class="breadcrumb" aria-label="ตำแหน่งหน้า"><NuxtLink to="/">หน้าหลัก</NuxtLink><span>/</span><NuxtLink to="/#places">จุดแวะน่ารัก</NuxtLink><span>/</span><span>{{ place.title }}</span></nav><div class="detail-grid"><div class="detail-photo"><img :src="asset(place.image)" :alt="placeImageAlt(place)" width="1000" height="1000" /></div><article class="detail-copy"><p class="eyebrow">A LOVELY LITTLE STOP · {{ place.category }}</p><h1>{{ place.title }}</h1><p class="detail-subtitle">{{ place.subtitle }}</p><span class="detail-duration"><Clock3 :size="18" /> เผื่อเวลา {{ place.duration }}</span><p>{{ place.description }}</p><div class="detail-tip"><Leaf :size="24" /><p>{{ place.tip }}</p></div><div class="detail-actions"><a class="button button-primary" :href="mapsUrl(place.map)" target="_blank" rel="noopener noreferrer"><Navigation :size="18" />เปิดแผนที่</a><NuxtLink to="/#planner" class="button button-outline">จัดแพลนของฉัน</NuxtLink></div><a :href="place.source" class="source-link" target="_blank" rel="noopener noreferrer"><BookOpen :size="15" /> ดูข้อมูลจากแหล่งต้นทาง</a><p class="detail-meta">ข้อมูลตรวจสอบ 20 พฤศจิกายน 2569<br>ภาพ: <a :href="imageAttribution.source" target="_blank" rel="noopener noreferrer">{{ imageAttribution.credit }}</a><br>เวลาและกิจกรรมอาจเปลี่ยนแปลง · โปรดตรวจสอบกับร้านก่อนเดินทาง</p></article></div><section class="more-stops"><p class="eyebrow">KEEP WANDERING</p><h2>เผื่ออยากแวะอีกนิด</h2><div class="more-links"><NuxtLink v-for="item in places.filter(p => p.slug !== place?.slug)" :key="item.slug" :to="`/places/${item.slug}`"><MapPin :size="18" />{{ item.title }}</NuxtLink></div></section></main><footer class="simple-footer">บางหลวง วันว่าง · A LITTLE ESCAPE, A LOVELY DAY.</footer></div></template>
